#pragma once
// M2 multi-mode firmware — DBC / custom-PID signal engine (Phase 12).
//
// Signal extraction (bit numbering, endianness, signedness, scaling,
// multiplexing, enums) driving dashboard, logging, and API from ONE
// definition. The definition is build-time generated by
// scripts/dbc_extract.py from the OEM database's curated DBCs — NO DBC
// text parsing happens in firmware (too heavy for the SAM3X8E).
//
// Bit numbering (DBC convention — Vector / cantools 44.x; an earlier
// revision of the extractor had this backwards, fixed 2026-10-09):
//  - Motorola (big-endian, @0): startBit = MSB position; the signal
//    occupies startBit going "down" (toward LSB), sawtooth across bytes.
//  - Intel (little-endian, @1): startBit = LSB position; bits run
//    startBit .. startBit+len-1, byte order little.
// Physical value = raw * factor1000/1000 + offset1000/1000 (integer math
// only — no float in firmware).
//
// Fail-closed decoding: a signal whose bit span reaches past the end of
// the received frame is SKIPPED — the callback is never invoked for it —
// so truncated frames can never produce plausible-but-wrong values from
// missing bits read as zero. The per-call skip count is exposed via
// truncatedSkips() (reset on every decode() entry).
//
// Evidence: VERIFIED = compiles. INFERRED = decode values untested
// against a real vehicle (the loopback harness exercises framing, not
// OEM signal semantics).

#include <Arduino.h>
#include <stdint.h>
#include "dbc_gen.h"

namespace dbcsig {

// One decoded signal delivered to the callback.
struct SignalVal {
    const char* name;     // signal name (from the DBC)
    int32_t phys1000;     // physical value * 1000
    int32_t raw;          // raw integer value
    const char* unit;     // unit string (may be "")
    const char* en;       // enum description, or nullptr
};

// Decode all signals of one CAN frame. Calls cb once per decoded
// signal (multiplexed signals only when their muxVal matches the
// multiplexer's current value). Returns the number of signals decoded.
// id matching: exact 11/29-bit match against the baked table.
// Signals whose bit span exceeds the frame length are skipped (fail
// closed); see truncatedSkips().
uint16_t decode(uint32_t id, bool ext, const uint8_t* data, uint8_t len,
                void (*cb)(const SignalVal& v, void* ctx), void* ctx);

// Number of signals skipped by the most recent decode() call because the
// frame was shorter than their bit span. Reset on every decode() entry.
uint16_t truncatedSkips();

// Look up one signal by message ID + signal name. Returns true and fills
// out when found (does not need a frame).
bool find(uint32_t id, bool ext, const char* sigName,
          const dbc::Sig*& sigOut, uint16_t& msgIdxOut);

// Table inventory (for console/API).
uint16_t msgCount();
uint16_t sigCount();
uint16_t enumCount();
uint8_t dbcCount();
const char* dbcName(uint8_t i);
// Message descriptor by index (for `dbc list`).
bool msgInfo(uint16_t idx, uint32_t& id, uint8_t& ext, uint8_t& dlc,
             uint16_t& nSig);

} // namespace dbcsig
